"""Conteúdo pesquisado em fontes oficiais em 25/10/2026; não efetua reservas."""
import json
from pathlib import Path
root=Path(__file__).resolve().parents[1]
p=root/'guides.json'
guides=json.loads(p.read_text(encoding='utf-8'))
data=json.loads((root/'paris2026.json').read_text(encoding='utf-8'))
for item in data['stages']:
    key=item['key']
    if key not in guides:
        guides[key]={'key':key,'photos':[],'history':[],'stops':[],'tips':[],'sources':[]}
    g=guides[key]
    g.update(title=item['title'],city=item['place'],reviewed='2026-10-25')
    g['tips']=[item['description']]+g['tips']
g=guides['champagne-reims']
g.update(kicker='Um dia em Champagne',intro='Reims, a maison Veuve Clicquot e as paisagens da Montagne de Reims, com tempo para pausas e deslocamentos acessíveis.',duration='07h30–19h30, incluindo deslocamentos',arrival='Veículo acessível desde Paris; reservar espaço e fixação para a cadeira motorizada.',booking='Veuve Clicquot é a preferência. Sessão de 05/11/2026, percurso, tarifa e política para menor ainda a confirmar.',accessibility='A maison declara visita, loja e café acessíveis mediante aviso na reserva. Confirmar especificamente cadeira motorizada, dimensões, elevador, sanitário e procedimento de emergência. Mirantes e vinhedos exigem verificação independente.',photo_tip='Registre a catedral, as paisagens e o grupo nos pontos permitidos; respeite as regras de fotografia nas caves.')
g['history']=['Champagne deve ser entendida como território vitícola e como tradição de produção, não apenas como uma bebida. Reims reúne patrimônio urbano e casas de champagne; os vinhedos ficam distribuídos por diferentes setores, ligados por rotas turísticas. Uma visita às caves na cidade não substitui um percurso pelas paisagens rurais.','A experiência proposta combina três olhares: a cidade de Reims, as caves da maison escolhida e as encostas da Montagne de Reims. A Veuve Clicquot, conhecida em português como Viúva Clicquot, integra o programa como preferência do grupo. O tempo disponível favorece uma única maison, sem acrescentar Épernay ao bate-volta.']
g['history'].append('Barbe-Nicole Clicquot assumiu a casa em 1805 após ficar viúva. A maison associa sua trajetória à inovação na produção, incluindo a mesa de remuage desenvolvida em 1816 para concentrar os depósitos das garrafas e obter vinhos límpidos. Essa história ajuda a compreender o trabalho apresentado na visita às caves.')
g['stops']=[{'title':'Reims e catedral','text':'Pausa para café e observação externa antes da sessão reservada; adaptar ao trânsito.'},{'title':'Veuve Clicquot — preferência','text':'Visita às caves e degustação para adultos, condicionadas à reserva e ao percurso acessível.'},{'title':'Montagne de Reims / Verzenay','text':'Percurso panorâmico com parada acessível, se confirmada; retorno sem adicionar Épernay.'}]
g['tips'] += ['Levar agasalho para a visita subterrânea e confirmar temperatura e piso com a maison.','Motorista sem degustação; solicitar opção sem álcool e política para a adolescente.','Tempo de estrada e horários da sessão são propostas, sem disponibilidade garantida.']
g['venues']=[
 {'name':'Veuve Clicquot — preferência do grupo','text':'Caves em Reims, 1 rue Albert Thomas. Calendário publicado: quarta a domingo de 04/11/2026 a 03/01/2027, 09h30–17h30; 05/11 está nesse período, mas a sessão não está confirmada. Experiência de 1 hora anunciada a €36 por adulto; confirmar preço e modalidade. Contato: visitscenter@veuve-clicquot.fr, +33 3 26 89 53 90. Visita privada a caves/vinhedos exige consulta separada.','access':'Acessibilidade anunciada mediante aviso; confirmar rota da cadeira motorizada e participação de Aline sem degustação alcoólica.','url':'https://www.veuveclicquot.com/en-gb/visitus.html'},
 {'name':'Ruinart — alternativa em Reims','text':'4 rue des Crayères: proposta que reúne caves, arquitetura, arte e degustação. Consultar sessão, duração e orçamento, sem somar à Veuve no mesmo dia por obrigação. Contato: visites@ruinart.com, +33 1 57 32 42 78.','access':'A maison informa acolhimento de pessoas com mobilidade reduzida; verificar especificamente a visita subterrânea e cadeira motorizada, sem inferir acesso completo a partir do pavilhão.','url':'https://www.ruinart.com/en-int/maison---4-rue-des-cray%C3%A8res-4ruedescrayeres.html'},
 {'name':'Épernay / Mercier — alternativa para outro programa','text':'Épernay e sua Avenue de Champagne podem substituir o dia em Reims em uma revisão futura. A Mercier fica em 68 avenue de Champagne; consultar experiências e agenda oficial. Não está agendada em 05/11.','access':'Confirmar elevador, percurso, equipamentos e política de menores diretamente; não presumir compatibilidade do trem interno com a cadeira.','url':'https://www.champagnemercier.com/en/visit-us'}]
g['sources']=[{'title':'Veuve Clicquot — visitas, agenda e contato','url':g['venues'][0]['url']},{'title':'Ruinart — visita e acessibilidade','url':g['venues'][1]['url']},{'title':'Comité Champagne — território e rotas','url':'https://www.champagne.fr/en/visit-champagne'},{'title':'Mercier — visitas em Épernay','url':g['venues'][2]['url']}]
g['sources'].append({'title':'Madame Clicquot — história da maison','url':'https://www.veuveclicquot.com/en-us/madameclicquot.html'})
guides['paris-eiffel']['sources'].append({'title':'Torre Eiffel — visita em cadeira de rodas','url':'https://www.toureiffel.paris/en/faq/getting-tower/can-visits-be-made-people-wheelchairs'})
guides['paris-louvre']['sources'].append({'title':'Louvre — acessibilidade e reservas','url':'https://www.louvre.fr/en/visit/accessibility'})
t=guides['toscana-rural']
t['intro']='Montepulciano, uma vinícola a escolher e Pienza/Val d’Orcia: paisagens, gastronomia e cultura do vinho no ritmo do grupo.'
t['venues']=[
 {'name':'Podere della Bruciata — candidata artesanal','text':'Pequena produtora de Montepulciano, com vinhos em quantidades limitadas e experiências de degustação em cantina ou vinhedo. É uma candidata alinhada à preferência por produção artesanal; solicitar proposta de almoço para seis em 30/10, idioma e duração. Contato: poderedellabruciata@gmail.com, +39 327 272 7130. Preço sob consulta.','access':'Não foi localizada confirmação técnica de acesso para a cadeira motorizada. Confirmar entrada, inclinações, piso, mesa e banheiro antes de escolher.','url':'https://www.poderedellabruciatawines.it/'},
 {'name':'Salcheto — alternativa com gastronomia','text':'Via di Villa Bianca 15, Montepulciano. A página oficial oferece visita com três vinhos a €27 por pessoa e opções privadas; almoço no restaurante Indigeno deve ser consultado separadamente. O valor de reserva exibido para restaurante não representa o preço da refeição. Contato: enoteca@salcheto.it, +39 0578 799031 (int. 1). Confirmar funcionamento em 30/10.','access':'Confirmar acesso da cadeira motorizada em todas as áreas contratadas, banheiro e condição do acesso viário; não considerar a visita integralmente acessível sem resposta da propriedade.','url':'https://salcheto.it/ospitalita/'},
 {'name':'Icario — alternativa para comparar','text':'Propriedade de Montepulciano com tours, degustações, arquitetura e projeto de arte. Consultar formato, preço e possibilidade de refeição; é alternativa à escolha principal, não uma segunda vinícola obrigatória no mesmo dia.','access':'Acessibilidade completa para cadeira motorizada ainda não confirmada. Pedir dimensões e trajeto sem escadas, além de sanitário acessível.','url':'https://www.icario.it/en/home/'}]
t['tips'] += ['Escolher uma única vinícola após comparar acesso real, almoço e orçamento; o roteiro não implica que as três estejam reservadas.','O ingresso/degustação não inclui transporte desde Roma. Aline precisa de programação sem degustação alcoólica.']
t['sources'] += [{'title':v['name'],'url':v['url']} for v in t['venues']]
t['reviewed']='2026-10-25'
p.write_text(json.dumps(guides,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
